import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const CreerDevoir = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [courses, setCourses] = useState([]);
  const [classes, setClasses] = useState([]);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    course_id: '',
    class_id: '',
    date_limite: '',
    fichier: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const token = localStorage.getItem('token');
      
      // Récupérer les cours
      const coursesResponse = await fetch('http://localhost:5000/api/courses/professeur', {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      const coursesData = await coursesResponse.json();
      if (coursesData.success) {
        setCourses(coursesData.data.courses);
      }

      // Récupérer les classes
      const classesResponse = await fetch('http://localhost:5000/api/classes/professeur', {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      const classesData = await classesResponse.json();
      if (classesData.success) {
        setClasses(classesData.data.classes);
      }
    } catch (error) {
      console.error('Erreur chargement données:', error);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('token');

      if (!formData.title || !formData.course_id || !formData.class_id || !formData.date_limite) {
        alert('❌ Tous les champs obligatoires doivent être remplis');
        return;
      }

      const response = await fetch('http://localhost:5000/api/devoirs/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });

      const result = await response.json();

      if (response.ok && result.success) {
        alert('✅ Devoir créé avec succès!');
        setFormData({
          title: '',
          description: '',
          course_id: '',
          class_id: '',
          date_limite: '',
          fichier: ''
        });
        navigate('/creer');
      } else {
        alert(`❌ Erreur: ${result.message || 'Erreur de création'}`);
      }
    } catch (error) {
      console.error('💥 Erreur:', error);
      alert('❌ Erreur de connexion au serveur');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: '20px', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Créer un Devoir</h1>
      
      <form onSubmit={handleSubmit} style={{ display: 'grid', gap: '20px' }}>
        
        {/* Titre du devoir */}
        <div>
          <label>Titre du Devoir *</label>
          <input
            type="text"
            name="title"
            value={formData.title}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px' }}
            placeholder="Ex: Exercice de mathématiques..."
          />
        </div>

        {/* Description */}
        <div>
          <label>Description</label>
          <textarea
            name="description"
            value={formData.description}
            onChange={handleInputChange}
            rows="4"
            style={{ width: '100%', padding: '10px' }}
            placeholder="Description du devoir..."
          />
        </div>

        {/* Cours */}
        <div>
          <label>Cours *</label>
          <select
            name="course_id"
            value={formData.course_id}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px' }}
          >
            <option value="">Sélectionnez un cours</option>
            {courses.map(course => (
              <option key={course.id} value={course.id}>
                {course.title} - {course.level}
              </option>
            ))}
          </select>
        </div>

        {/* Classe */}
        <div>
          <label>Classe *</label>
          <select
            name="class_id"
            value={formData.class_id}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px' }}
          >
            <option value="">Sélectionnez une classe</option>
            {classes.map(classe => (
              <option key={classe.id} value={classe.id}>
                {classe.nom} - {classe.niveau}
              </option>
            ))}
          </select>
        </div>

        {/* Date limite */}
        <div>
          <label>Date Limite *</label>
          <input
            type="date"
            name="date_limite"
            value={formData.date_limite}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px' }}
          />
        </div>

        {/* Fichier */}
        <div>
          <label>Fichier (optionnel)</label>
          <input
            type="text"
            name="fichier"
            value={formData.fichier}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '10px' }}
            placeholder="Nom du fichier ou URL..."
          />
        </div>

        <button 
          type="submit" 
          disabled={loading}
          style={{ 
            padding: '15px', 
            backgroundColor: loading ? '#ccc' : '#007bff', 
            color: 'white', 
            border: 'none', 
            borderRadius: '5px',
            cursor: loading ? 'not-allowed' : 'pointer'
          }}
        >
          {loading ? 'Création en cours...' : 'Créer le Devoir'}
        </button>
      </form>
    </div>
  );
};

export default CreerDevoir;
